from pathlib import Path
import json,hashlib,sys,copy
P=Path(__file__).resolve().parent;L=P.parents[3];sys.path.insert(0,str(L));from substantive_impact import validate,certificate
sha=lambda b:hashlib.sha256(b).hexdigest();sources=json.loads((P/'source.json').read_text());by={s['number']:s for s in sources};draft={};spec={}
def replace(n,old,new):
 body=draft.get(n,by[n]['source_xml']);assert body.count(old)==1,(n,old);draft[n]=body.replace(old,new)
def add(n,text):draft[n]=draft.get(n,by[n]['source_xml'])+'\n<p>'+text+'</p>\n'
def describe(n,mid,cl,kind,reason,before,after,q1,q2,pop,transition,limits,extra=None):
 spec[n]=dict(mid=mid,cl=cl,kind=kind,reason=reason,before=before,after=after,q1=q1,q2=q2,pop=pop,transition=transition,limits=limits,extra=extra)
replace('L242-12-1',"Dans ce cas, il n'est tenu compte d'aucune exonération dont pourrait bénéficier le cotisant.","Dans ce calcul provisoire, il est tenu compte des exonérations dont les conditions d'application et le montant peuvent être déterminés pour la période considérée à partir des informations exactes, à jour et légalement disponibles à l'organisme. La seule absence de la déclaration ne justifie pas de les écarter. Les exonérations dont les conditions ou le montant ne peuvent pas encore être établis sont pris en compte lors de la régularisation, dans leurs conditions propres.")
add('L242-12-1',"La prise en compte provisoire des exonérations établies s'applique aux taxations provisoires notifiées à compter de l'entrée en vigueur de la loi de simplification, y compris pour une période antérieure. Elle n'ouvre aucun accès nouveau aux données, ne dispense pas de déclarer les éléments manquants et ne modifie ni l'assiette, ni les taux, ni le montant des cotisations et contributions finalement dus après régularisation. Les droits à exonération, restitution et recours antérieurs sont conservés, sans réouverture des décisions devenues définitives par le seul effet du présent article.")
replace('R243-15',"<p>II. - La taxation déterminée en vertu du I", "<p>Pour le calcul provisoire du I, les exonérations dont les conditions d'application et le montant sont établis pour la période considérée par des informations exactes, à jour et légalement disponibles à l'organisme sont prises en compte conformément à l'article L. 242-12-1. Cette règle ne supprime ni les majorations de base du présent I pour les éléments manquants, ni les données nécessaires à la liquidation définitive. Elle ne crée pas d'exonération de la contribution distincte du III.</p>\n<p>II. - La taxation déterminée en vertu du I")
add('R243-15',"La prise en compte provisoire des exonérations établies s'applique aux taxations du I notifiées à compter de l'entrée en vigueur de la loi de simplification dans les conditions de l'article L. 242-12-1. Les modalités, délais et garanties des II à V, les régularisations et les droits antérieurs sont conservés. Il ne s'agit ni d'une remise des cotisations définitivement dues ni d'un taux nouveau.")
replace('R243-15',"<p>V .- Ces dispositions ne sont pas applicables", "<p>V .- Les calculs et notifications des I et II ne peuvent être fondés sur la seule absence d'une déclaration mensuelle à néant dont l'employeur est dispensé en application du I de l'article R. 133-14. Cette règle ne dispense pas de données qui restent dues, notamment au titre du dernier mois comportant un emploi, d'un versement ou d'une régularisation déclarable ou de l'obligation annuelle du III.</p>\n<p>Ces dispositions ne sont pas applicables")
for n in ['L242-12-1','R243-15']:
 describe(n,'taxation-provisoire-exonerations-etablies','payment_timing_relief','payment_deferred',"Prend en compte les exonérations déjà complètement établies dans le seul calcul provisoire, au lieu de faire avancer une somme qui serait ensuite régularisée ; aucun taux ni droit final à exonération n'est modifié.","La taxation provisoire écarte toute exonération ; la liquidation définitive rétablit les avantages éligibles après déclaration.","Le calcul provisoire inclut les seules exonérations dont conditions et montant sont établis ; les autres attendent la régularisation. Dette finale inchangée.","Dans ce cas, il n'est tenu compte d'aucune exonération dont pourrait bénéficier le cotisant." if n=='L242-12-1'else"Lorsque les données nécessaires au calcul des cotisations ou des contributions n'ont pas été transmises par l'employeur","La seule absence de la déclaration ne justifie pas de les écarter."if n=='L242-12-1'else"les exonérations dont les conditions d'application et le montant sont établis pour la période considérée",'Cotisants soumis à taxation provisoire ; pour R243-15, employeurs du I seulement, sans extension au calcul DOETH du III.',"Taxations provisoires notifiées après l'entrée en vigueur, y compris périodes anciennes ; régularisation définitive et recours inchangés.","Effet de trésorerie seulement : aucune baisse permanente de cotisations ni nouvelle exonération. Si le montant d'un avantage dépend des données manquantes, il n'est pas supposé connu. Montant national et coût de trésorerie public inconnus.")
spec['R243-15']['reason']+=" Coordonne aussi le V avec la dispense de DSN à néant déjà prévue par le R133-14 proposé, sans nouvelle réduction autonome."
spec['R243-15']['limits']+=" La dispense mensuelle déjà proposée ne supprime ni dernier mois d'emploi, ni régularisation, ni déclaration annuelle DOETH ; la source V favorable reste conservée dans son champ."
spec['R243-15']['extra']=dict(kind='coordination',measure_id='dsn-neant-dispense-sans-emploi',description="Évite que la taxation provisoire rétablisse l'autorisation préalable déjà retirée par le R133-14 proposé.",before="Le V vise seulement l'admission d'une demande préalable d'absence de déclaration pour absence d'emploi.",after="Aucune taxation I/II pour le seul défaut d'une DSN à néant dispensée par R133-14 ; données encore dues et DOETH annuelle maintenues.",unit='legal_duty',affected_population="Employeurs bénéficiant de la dispense mensuelle de R133-14 après cessation de la dernière relation d'emploi, sans donnée déclarable.",conditions_and_transition="Champ et entrée en vigueur de la dispense déjà proposée ; ancienne dispense individuelle conservée dans son champ.",replacement_or_new_burdens="Aucun nouveau dossier ni taxe supprimée ; coordination de la même dispense, pas nouveau gain CRPA.",source_quote="l'organisme a admis la demande préalable de l'employeur de ne plus adresser la déclaration",proposed_quote="Les calculs et notifications des I et II ne peuvent être fondés sur la seule absence d'une déclaration mensuelle à néant")
replace('L243-6-5',"<p>III.-La possibilité de conclure une transaction sur un ou plusieurs chefs de redressement faisant suite à un contrôle prévu à l'article L. 243-7 et faisant l'objet d'un recours devant la commission de recours amiable de l'organisme de recouvrement est suspendue à compter de la date de ce recours et jusqu'à la date de la décision de cette commission. Cette possibilité n'est rétablie à l'issue de cette période que lorsque le   tribunal judiciaire spécialement désigné en application de l'article L. 211-16 du code de l'organisation judiciaire a été saisi. </p>","<p>III.-Une transaction sur un ou plusieurs chefs de redressement peut être demandée, négociée et conclue pendant l'examen d'un recours par la commission de recours amiable et après sa décision, sans être subordonnée à la saisine du tribunal judiciaire. Elle reste soumise aux conditions du I et du II. L'ouverture de la négociation ne dessaisit ni la commission ni une juridiction déjà saisie et ne vaut pas renonciation à un recours. Elle ne dispense pas le cotisant de préserver les délais de ses recours ; les effets interruptifs attachés à la demande de transaction restent ceux prévus par les dispositions réglementaires applicables.</p>")
add('L243-6-5',"La suppression de la suspension pendant le recours amiable et de la saisine judiciaire préalable s'applique aux demandes présentées ou en cours à l'entrée en vigueur de la loi de simplification, y compris lorsqu'elles concernent des chefs de redressement antérieurs non définitifs. Les transactions, créances, prescriptions et recours antérieurs restent applicables dans leur champ ; aucune décision devenue définitive n'est rouverte. Aucune transaction n'est imposée à une partie, et les autres conditions, approbations et contrôles prévus au présent article demeurent.")
replace('R243-45-1',"<p>La demande n'est recevable qu'après réception de la mise en demeure prévue à l'article L. 244-2.</p>","<p>La demande peut être présentée avant ou après réception d'une mise en demeure, dès lors que les sommes et l'objet de la transaction peuvent être identifiés et que les conditions de l'article L. 243-6-5 sont remplies. Un recours pendant devant la commission de recours amiable ou l'absence de saisine judiciaire ne la rend pas irrecevable.</p>")
replace('R243-45-1',"<p>4° Les références de la mise en demeure couvrant les sommes faisant l'objet de la demande.</p>","<p>4° Lorsqu'une mise en demeure a été adressée, ses références pour les sommes faisant l'objet de la demande.</p>")
replace('R243-45-1',"En l'absence de réception des éléments manquants dans un délai de vingt jours suivant la demande de complément, la demande de transaction est réputée caduque.","L'absence de réception des éléments manquants dans les vingt jours ne rend pas la demande caduque : elle reste en attente de ces éléments, sans nouveau dépôt. Le délai de réponse de trente jours ne commence qu'à réception des éléments nécessaires. Chacune des parties conserve la faculté d'abandon prévue ci-après ; le silence ne vaut pas conclusion d'une transaction.")
add('R243-45-1',"Les suppressions de l'attente obligatoire d'une mise en demeure, de l'obstacle lié au recours amiable ou à l'absence de saisine judiciaire et de la caducité automatique à vingt jours s'appliquent aux demandes présentées ou en cours à l'entrée en vigueur de la loi de simplification. Elles ne rouvrent pas une demande déjà définitivement éteinte ni une décision devenue définitive. Les conditions d'actualité des déclarations et paiements, les concessions réciproques, la liberté de ne pas transiger, l'approbation de l'autorité de contrôle et les garanties de recours sont maintenues. Aucun délai de recours judiciaire n'est interrompu du seul fait de négociations, en dehors des effets expressément prévus par les textes qui le régissent.")
describe('L243-6-5','transaction-sociale-sans-parcours-contentieux-impose','material_reduction','obligation_removed',"Retire l'interdiction de transiger pendant le recours amiable et la nécessité de saisir le juge pour rouvrir cette faculté, sans supprimer concessions, contrôle ni exclusions de fraude.","La transaction est suspendue durant le recours amiable puis n'est rétablie qu'après saisine judiciaire.","La transaction peut être examinée et conclue pendant ou après le recours amiable sans saisine judiciaire imposée ; les recours et conditions de fond demeurent.","Cette possibilité n'est rétablie à l'issue de cette période que lorsque le   tribunal judiciaire spécialement désigné", "sans être subordonnée à la saisine du tribunal judiciaire",'Cotisants et organismes de recouvrement pour sommes non définitives dans le champ transactionnel limité par les I et II.',"Demandes nouvelles ou en cours après entrée en vigueur ; aucune réouverture de décision définitive ni transaction forcée.","Cette faculté ne suspend pas par elle-même les délais contentieux. Les sommes définitives, le travail dissimulé, les manœuvres dilatoires et les approbations demeurent hors de l'allègement. Aucun gain national chiffré.")
describe('R243-45-1','transaction-sociale-sans-parcours-contentieux-impose','material_reduction','obligation_removed',"Retire la mise en demeure comme préalable obligatoire et la caducité automatique de la demande incomplète à vingt jours ; coordonne l'accès pendant le recours amiable sans imposer un procès.","La demande ne peut être déposée qu'après réception de la mise en demeure et devient caduque après vingt jours sans compléments.","Demande possible avant mise en demeure si sommes identifiables ; demande incomplète en attente sans redépôt. Les trente jours sur dossier complet et la faculté d'abandon restent.","La demande n'est recevable qu'après réception de la mise en demeure prévue à l'article L. 244-2.","La demande peut être présentée avant ou après réception d'une mise en demeure",'Cotisants admissibles à une transaction, y compris ceux dont le recours amiable est pendant.',"Demandes nouvelles et pendantes après entrée en vigueur ; caducités et décisions antérieures définitives non rouvertes.","Pas de droit à obtenir une transaction : dettes non définitives, conditions déclaratives, concessions réciproques, approbation et délais judiciaires conservés. Le délai administratif sur dossier complet n'est pas allongé.",extra=dict(kind='relief_extended',measure_id='transaction-sociale-sans-parcours-contentieux-impose',description="Conservation de la demande incomplète sans caducité automatique ni nouveau dépôt après vingt jours.",before="Absence de compléments reçus sous vingt jours : caducité automatique de la demande.",after="Demande en attente des compléments, sans caducité pour ce seul délai ni redépôt ; liberté d'abandon maintenue.",unit='legal_duty',affected_population='Cotisants ayant demandé une transaction et devant encore compléter leur dossier.',conditions_and_transition="Demandes nouvelles ou encore pendantes à l'entrée en vigueur, sans réouverture des caducités déjà définitives.",replacement_or_new_burdens="Aucun formulaire ni attestation de remplacement ; les seuls éléments nécessaires au dossier restent dus.",source_quote="la demande de transaction est réputée caduque",proposed_quote="elle reste en attente de ces éléments, sans nouveau dépôt."))
replace('L243-13',"Cette période peut être prorogée une fois à la demande expresse de la personne contrôlée ou de l'organisme de recouvrement.","Cette période peut être prorogée une fois à la seule demande expresse de la personne contrôlée. L'organisme de recouvrement ne peut imposer cette prorogation par sa propre demande.")
add('L243-13',"Cette suppression de la prorogation à la demande de l'organisme s'applique aux contrôles engagés à compter de l'entrée en vigueur de la loi de simplification. Les contrôles antérieurs restent soumis à leur régime. La prolongation demandée par le cotisant, les exceptions prévues aux 1° à 5° du I et le champ du II sont conservés ; aucune dette, garantie de débat contradictoire ou voie de recours n'est supprimée.")
describe('L243-13','controle-tpe-sans-prorogation-unilaterale','material_reduction','deadline_reduced',"Supprime la faculté pour l'organisme de demander seul la prorogation du contrôle de trois mois, tout en conservant celle du cotisant et les exceptions légales.","Contrôle de trois mois des entreprises de moins de vingt salariés et indépendants, prorogeable une fois à la demande du cotisant ou de l'organisme.","La prorogation de droit commun ne peut venir que de la demande expresse du cotisant ; exceptions de fraude, obstruction, documentation et report ainsi que groupes inchangées.","à la demande expresse de la personne contrôlée ou de l'organisme de recouvrement", "à la seule demande expresse de la personne contrôlée",'Entreprises rémunérant moins de vingt salariés et indépendants, hors exclusions et groupes du II.',"Contrôles engagés après entrée en vigueur ; demandes de prolongation du cotisant et contrôles anciens conservés.","Pas de plafond absolu de trois mois dans les cas dérogatoires ; pas de suppression du délai contradictoire ni extinction des cotisations. Durée de la prorogation non inventée.")
replace('L244-2',"d'un avertissement par lettre recommandée de l'autorité compétente de l'Etat", "d'un avertissement de l'autorité compétente de l'Etat adressé par lettre recommandée ou par tout autre moyen légal permettant de donner date certaine à sa réception")
add('L244-2',"La faculté de choisir un autre moyen légal donnant date certaine à réception s'applique aux avertissements émis à compter de l'entrée en vigueur de la loi de simplification. La lettre recommandée reste possible. Le délai d'un mois, le contenu précis et motivé, les garanties de réception et les recours restent exigés. Les avertissements et procédures antérieurs conservent leur régime ; aucune irrégularité passée n'est validée par le seul effet de cette disposition.")
replace('R243-48',"l'organisme créancier en avise le débiteur par lettre recommandée.","l'organisme créancier en avise le débiteur par lettre recommandée ou par tout autre moyen légal permettant de donner date certaine à sa réception.")
add('R243-48',"Cette faculté s'applique aux avis accompagnant les demandes d'inscription présentées à compter de l'entrée en vigueur de la loi de simplification. Elle ne supprime ni l'avis concomitant au débiteur ni la preuve de sa réception. Les règles légales de notification et de protection du destinataire demeurent applicables ; un simple envoi électronique ne vaut pas, à lui seul, réception certaine. Les inscriptions, avis et recours antérieurs restent régis par leurs règles propres.")
for n in ['L244-2','R243-48']:
 describe(n,'recouvrement-notifications-sans-recommande-exclusif','material_reduction','obligation_removed',"Supprime l'exclusivité du recommandé pour la seule notification visée, avec maintien de l'avis, d'un moyen légal et de la preuve d'une date certaine de réception.","Un avertissement du ministère public ou l'avis d'inscription du privilège impose le recommandé, selon l'article concerné.","Le recommandé demeure possible ; un autre moyen légal prouvant la réception certaine est admis sans supprimer information, motivation ou recours.","d'un avertissement par lettre recommandée"if n=='L244-2'else"en avise le débiteur par lettre recommandée", "par tout autre moyen légal permettant de donner date certaine à sa réception",'Autorités et organismes notifiant ; cotisants destinataires des seuls avertissements ou avis visés.',"Avertissements émis ou inscriptions demandées après entrée en vigueur ; procédures anciennes et irrégularités passées non validées.","Aucune présomption qu'un courriel simple suffit. Pas de suppression de l'avis, du mois de régularisation législatif ni des droits du débiteur ; coûts de notification et économies nationales non chiffrés.")
replace('R243-6-3',"Cette désignation peut être modifiée sur demande de l'entreprise et après autorisation du directeur de l'Agence centrale des organismes de sécurité sociale. Dans ce cas, une nouvelle procédure de désignation est engagée.","L'entreprise peut demander le changement de son interlocuteur unique en désignant, dans sa demande adressée au directeur de l'Agence centrale des organismes de sécurité sociale, un organisme figurant sur la liste mentionnée aux articles L. 213-1 et L. 752-1. Cette demande vaut option sans autorisation préalable ni reprise de la procédure de proposition et de désignation initiale. Le changement prend effet le 1er janvier suivant la réception de la demande ; il ne recommence pas, à lui seul, la période de maintien dans le régime prévue à l'alinéa précédent. Le choix s'exerce sans déroger aux affectations obligatoires prévues à l'article L. 243-1-2 ou prises en application de l'article R. 243-8-1, pour les personnels qu'elles concernent. Le même organisme assure le recouvrement de l'ensemble des établissements relevant de cette option.")
add('R243-6-3',"La suppression de l'autorisation de changement s'applique aux demandes présentées ou en cours à l'entrée en vigueur de la loi de simplification, sans nouveau dépôt. Les désignations et actes antérieurs conservent leurs effets. L'option n'efface aucune dette, n'interrompt aucun contrôle ou recours et ne modifie ni les échéances, ni les déclarations, ni les exonérations opposables. Elle ne supprime pas le régime obligatoire de versement en lieu unique du I ni les affectations spéciales applicables.")
describe('R243-6-3','versement-unique-fin-autorisation','material_reduction','authorization_removed',"Retire l'autorisation préalable et la reprise de la procédure initiale pour changer d'interlocuteur unique dans le régime obligatoire ; garde l'unicité du versement et les affectations spéciales.","Un changement d'organisme demandé par l'entreprise requiert autorisation du directeur puis nouvelle procédure de désignation.","La demande existante vaut option pour un organisme de la liste, effet au 1er janvier suivant ; elle ne recommence pas la période de maintien. Désignation initiale et régime obligatoire conservés.","après autorisation du directeur de l'Agence centrale des organismes de sécurité sociale", "Cette demande vaut option sans autorisation préalable ni reprise de la procédure de proposition et de désignation initiale.",'Entreprises du régime obligatoire R243-6-3 : seuils 250/500 et établissements multiples conservés, affectations spéciales réservées.',"Demandes nouvelles ou pendantes après entrée en vigueur ; changement au 1er janvier suivant réception, sans redépôt.","La mesure partage le même identifiant que l'option de R243-8 déjà proposée, sans compter deux fois une autorisation abolie. Pas de droit de choisir un collecteur contraire à L243-1-2/R243-8-1 ni de fragmentation de l'entreprise. Coûts de migration inconnus.")
replace('R243-11',"si les conditions suivantes sont remplies : <br />\n<br />1° Aucun retard de paiement n'a été constaté au cours des vingt-quatre mois précédents ; <br />\n<br />2° Le montant des majorations et pénalités qui seraient applicables est inférieur à la valeur mensuelle du plafond de la sécurité sociale.","si le montant des majorations et pénalités qui seraient applicables est inférieur à la valeur mensuelle du plafond de la sécurité sociale. Un retard de paiement constaté au cours des vingt-quatre mois précédents ne prive pas, à lui seul, le cotisant de cette dispense.")
add('R243-11',"La suppression de la condition d'absence de retard antérieur s'applique aux échéances de cotisations et contributions exigibles à compter de l'entrée en vigueur de la loi de simplification. Le respect des obligations déclaratives, le règlement ou le plan sous trente jours, le respect du plan et le plafond des accessoires restent nécessaires. Cette dispense ne porte que sur les accessoires visés au présent article ; les cotisations dues, les autres pénalités, les remises et recours ouverts dans leur champ et les situations antérieures restent régis par leurs dispositions propres.")
describe('R243-11','retard-regularise-sans-condition-de-premier-incident','material_reduction','relief_extended',"Étend la dispense de majorations pour une régularisation rapide en retirant la condition d'absence de retard au cours des vingt-quatre mois précédents.","Même si le cotisant régularise sous trente jours ou respecte un plan, un retard dans les vingt-quatre mois précédents ferme la dispense.","Un retard antérieur ne ferme plus la dispense ; obligations déclaratives, trente jours, plan respecté et accessoires inférieurs au plafond mensuel restent nécessaires.","Aucun retard de paiement n'a été constaté au cours des vingt-quatre mois précédents", "Un retard de paiement constaté au cours des vingt-quatre mois précédents ne prive pas, à lui seul, le cotisant de cette dispense.",'Cotisants respectant leurs déclarations et régularisant leur paiement, avec accessoires sous le plafond mensuel.',"Nouvelles échéances exigibles après réforme ; régimes anciens et autres remises favorables conservés.","Vraie remise d'accessoires sous conditions, non simple report : le principal reste dû. Aucun taux social, dispositif de fraude ou pénalité distincte n'est supprimé ; perte de recettes non chiffrée.")
replace('R243-12',"Cette pénalité est appliquée pour chaque mois ou fraction de mois de retard.","Pour une même échéance déclarative et les personnes auxquelles se rapporte le manquement, cette pénalité n'est appliquée qu'une fois ; la seule persistance du même retard ne fait pas naître une nouvelle pénalité mensuelle. Les manquements relatifs à des échéances déclaratives distinctes restent appréciés séparément.")
add('R243-12',"La suppression de la répétition mensuelle s'applique aux manquements relatifs aux échéances déclaratives postérieures à l'entrée en vigueur de la loi de simplification. Le taux par salarié, la base d'effectif et le plafond favorable en cas de retard n'excédant pas cinq jours demeurent dans leurs conditions propres. Les obligations de déclarer, les cotisations et les sanctions distinctes légalement applicables restent dues dans leur champ, sous réserve de la règle de non-cumul de l'article R. 243-14. Les manquements antérieurs et leurs recours conservent leur régime.")
describe('R243-12','declaration-tardive-sans-penalite-mensuelle-repetee','material_reduction','relief_extended',"Retire le cumul automatique d'une nouvelle pénalité à chaque mois ou fraction de mois pour le même défaut déclaratif ; maintient la pénalité initiale et les déclarations distinctes.","Pénalité de 1,5 % du plafond mensuel par salarié, répétée chaque mois ou fraction de mois pour un même retard.","Même pénalité initiale, sans répétition mensuelle du même manquement ; échéances distinctes, plafond cinq jours et non-cumul conservés.","Cette pénalité est appliquée pour chaque mois ou fraction de mois de retard.","cette pénalité n'est appliquée qu'une fois",'Employeurs tardifs ou ayant omis un salarié, sans remise de leurs déclarations et cotisations.',"Manquements aux échéances déclaratives après réforme ; anciens manquements et voies de recours inchangés.","Baisse d'une pénalité administrative, pas d'un taux de cotisation. Le délai de déclaration n'est pas prolongé et les droits sociaux ne deviennent pas facultatifs. Recettes et effet d'incitation non chiffrés.")
# The reduction concerns an administrative penalty, not a contribution or tax rate.
retained={
'L243-5':"La remise des pénalités, majorations et frais en sauvegarde/redressement/liquidation protège déjà le débiteur ; supprimer l'article retirerait cet avantage. L'exception de travail dissimulé et la date légale du 1er juillet 2026 sont conservées, sans nouvelle formalité.",
'L243-6':"Les prescriptions de remboursement, correction AT/MP couvrant toute la période rectifiée, protection des prestations acquises et remboursement sous quatre mois sont des garanties du cotisant/assuré. Aucune demande en double ni support exclusif n'est imposé dans cet article ; sa suppression retirerait des droits.",
'L243-6-6':"La communication de l'échéancier et son extension aux cotisations patronales complémentaires, avec mandat entre créanciers, évitent déjà plusieurs démarches. Ce calendrier n'est pas une remise de cotisations et n'exige pas de nouvelle inscription ; le supprimer fermerait une facilité.",
'R243-13':"La pénalité distingue minoration de rémunération, autres erreurs et nomenclature ; aucune seconde production précise n'est imposée par ces trois règles. Les taux sont sous le plafond législatif de L133-5-4 et le non-cumul de R243-14 demeure. Modifier le seul libellé serait cosmétique ; l'effet sur les droits individuels d'un changement du contrôle de nomenclature n'est pas établi.",
'R243-14':"La règle interdit le cumul de pénalités pour les mêmes faits, sous sa réserve fiscale propre. La retirer exposerait les employeurs à une double sanction ; aucune obligation déclarative ou taux nouveau n'est créé par son maintien.",
'R243-17':"Exemption de la majoration initiale pour certains contrôles, réduction à 0,1 % si paiement sous trente jours et dispense de complément si retard administratif supérieur à deux mois sont favorables. Les exceptions fraude/abus/obstacle et seuil annuel sont conservés ; pas de nouvelle copie ni formulaire identifié.",
'R243-18':"Le délai de six ans et l'assiette limitée au seul manquement réitéré bornent la majoration de L243-7-6. Ils n'imposent pas une seconde déclaration ; retirer l'article créerait une incertitude sur cette garantie et ne supprime pas la majoration législative.",
'R243-19':"La compétence de liquidation et le délai d'un mois après notification sont nécessaires au recouvrement et à sa contestation. Les renvois aux sanctions gardent leurs régimes propres, y compris l'extinction prospective C3S ; les énumérer ne rétablit pas une contribution supprimée ni ne retire une remise.",
'R243-26':"Le délai supplémentaire d'un mois après mise en demeure protège l'entreprise utilisatrice tenue subsidiairement après défaillance de l'ETT et insuffisance de garantie. Ni la mission ni le contrat unique ne suppriment la dette de cotisations ; retirer cette règle retirerait le délai favorable.",
'R243-46':"L'inscription au registre et le greffe compétent rendent le privilège opposable et identifiable ; l'entreprise hors métropole bénéficie d'un circuit unique à Paris pour ses créances métropolitaines. Aucune formalité privée supplémentaire ou double dépôt n'est démontré dans ces deux alinéas.",
'R243-51':"L'inscription peut être contestée et la contestation doit apparaître publiquement, à l'initiative du créancier, du greffe ou du débiteur. Le certificat garantit la concordance de l'inscription demandée avec le litige ; aucun autre justificatif équivalent déjà admis n'est démontré dans les pièces lues. Les droits de mention et suppression restent entiers ; la norme n'est pas reformulée.",
'R243-53':"La mention de saisie, sa preuve, les quatre informations publiques, la mainlevée et la suppression automatique après dix ans assurent l'exactitude du registre et la fin d'une publicité devenue sans objet. Supprimer la mainlevée ou l'échéance pénaliserait le débiteur ; aucune seconde certification identique effectivement requise n'est établie.",
'R243-59-6-A':"Les dates de première visite ou de début du contrôle sur pièces et d'envoi de la lettre d'observations rendent mesurable la garantie de trois mois. Les supprimer faciliterait une durée indéterminée. La réforme de L243-13 retire une prorogation mais ne déplace pas ces bornes ; aucune nouvelle démarche ne résulte du maintien.",
'R243-59-6':"L'information de clôture et l'interdiction de contrôler à nouveau la période antérieure protègent le cotisant quand le délai de L243-13 est dépassé. Ces garanties restent opérantes avec la prorogation limitée à sa demande ; aucune nouvelle procédure ni extinction générale des cotisations n'est déduite de ce maintien."
}
